     1→/**
     2→ * Supabase Client Configuration and Auth Helper Functions
     3→ * Based on proven architecture from Finkargo Pre-Approval System
     4→ */
     5→import { createClient } from '@supabase/supabase-js';
     6→import type { SupabaseClient, Session, User, AuthError } from '@supabase/supabase-js';
     7→
     8→// Environment variables
     9→const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
    10→const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
    11→
    12→if (!supabaseUrl || !supabaseAnonKey) {
    13→  throw new Error('Missing Supabase environment variables. Check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in .env');
    14→}
    15→
    16→/**
    17→ * Supabase client instance with auto-refresh and session persistence
    18→ */
    19→export const supabase: SupabaseClient = createClient(supabaseUrl, supabaseAnonKey, {
    20→  auth: {
    21→    autoRefreshToken: true,      // Auto-refresh tokens before expiry
    22→    persistSession: true,         // Persist session in localStorage
    23→    detectSessionInUrl: true,     // Handle OAuth callbacks
    24→    storage: window.localStorage, // Store session data
    25→  },
    26→  global: {
    27→    headers: {
    28→      'x-application-name': 'Finkargo Automation Hub',
    29→    },
    30→  },
    31→});
    32→
    33→/**
    34→ * Sign in with email and password
    35→ */
    36→export const signIn = async (
    37→  email: string,
    38→  password: string
    39→): Promise<{ user: User | null; session: Session | null; error: AuthError | null }> => {
    40→  const { data, error } = await supabase.auth.signInWithPassword({
    41→    email,
    42→    password,
    43→  });
    44→
    45→  if (error) {
    46→    console.error('Sign in error:', error.message);
    47→    return { user: null, session: null, error };
    48→  }
    49→
    50→  return { user: data.user, session: data.session, error: null };
    51→};
    52→
    53→/**
    54→ * Register new user with email and password
    55→ */
    56→export const signUp = async (
    57→  email: string,
    58→  password: string,
    59→  metadata?: Record<string, any>
    60→): Promise<{ user: User | null; session: Session | null; error: AuthError | null }> => {
    61→  const { data, error } = await supabase.auth.signUp({
    62→    email,
    63→    password,
    64→    options: {
    65→      data: metadata || {},
    66→    },
    67→  });
    68→
    69→  if (error) {
    70→    console.error('Sign up error:', error.message);
    71→    return { user: null, session: null, error };
    72→  }
    73→
    74→  return { user: data.user, session: data.session, error: null };
    75→};
    76→
    77→/**
    78→ * Sign out current user
    79→ */
    80→export const signOut = async (): Promise<{ error: AuthError | null }> => {
    81→  const { error } = await supabase.auth.signOut();
    82→
    83→  if (error) {
    84→    console.error('Sign out error:', error.message);
    85→    return { error };
    86→  }
    87→
    88→  return { error: null };
    89→};
    90→
    91→/**
    92→ * Get current authenticated user
    93→ */
    94→export const getCurrentUser = async (): Promise<User | null> => {
    95→  const { data: { user }, error } = await supabase.auth.getUser();
    96→
    97→  if (error) {
    98→    console.error('Get user error:', error.message);
    99→    return null;
   100→  }
   101→
   102→  return user;
   103→};
   104→
   105→/**
   106→ * Get active session
   107→ */
   108→export const getSession = async (): Promise<Session | null> => {
   109→  const { data: { session }, error } = await supabase.auth.getSession();
   110→
   111→  if (error) {
   112→    console.error('Get session error:', error.message);
   113→    return null;
   114→  }
   115→
   116→  return session;
   117→};
   118→
   119→/**
   120→ * Refresh session
   121→ */
   122→export const refreshSession = async (): Promise<{ session: Session | null; error: AuthError | null }> => {
   123→  const { data, error } = await supabase.auth.refreshSession();
   124→
   125→  if (error) {
   126→    console.error('Refresh session error:', error.message);
   127→    return { session: null, error };
   128→  }
   129→
   130→  return { session: data.session, error: null };
   131→};
   132→

